"""
Observability tests.

Validates externally observable middleware behaviour:
  - X-Request-ID response header presence and uniqueness
  - Health/ready endpoint exclusion from request logging middleware
  - Readiness probe checks (database, Redis)
  - Security headers wired by SecurityHeadersMiddleware
"""

import re

from httpx import AsyncClient


class TestRequestId:
    """X-Request-ID header generated by RequestLoggingMiddleware."""

    async def test_response_includes_x_request_id(self, client: AsyncClient, admin_token: str):
        h = {"Authorization": f"Bearer {admin_token}"}
        r = await client.get("/api/v1/shipments", headers=h)
        assert r.status_code == 200

        rid = r.headers.get("X-Request-ID")
        assert rid is not None, "X-Request-ID header missing"
        assert re.fullmatch(r"[0-9a-f]{32}", rid), f"Expected 32-char hex, got: {rid}"

    async def test_request_id_unique_per_request(self, client: AsyncClient, admin_token: str):
        h = {"Authorization": f"Bearer {admin_token}"}
        r1 = await client.get("/api/v1/shipments", headers=h)
        r2 = await client.get("/api/v1/shipments", headers=h)

        rid1 = r1.headers.get("X-Request-ID")
        rid2 = r2.headers.get("X-Request-ID")
        assert rid1 != rid2, "Two requests should get different X-Request-ID values"

    async def test_health_skips_request_id(self, client: AsyncClient):
        r = await client.get("/health")
        assert r.status_code == 200
        assert "X-Request-ID" not in r.headers

    async def test_ready_skips_request_id(self, client: AsyncClient):
        r = await client.get("/ready")
        # May be 200 or 503 depending on Redis — either way, no request ID
        assert "X-Request-ID" not in r.headers


class TestReadinessProbe:
    """GET /ready checks database and Redis health."""

    async def test_ready_reports_database_ok(self, client: AsyncClient):
        r = await client.get("/ready")
        body = r.json()
        assert body["checks"]["database"] == "ok"

    async def test_ready_reports_redis_ok(self, client: AsyncClient):
        r = await client.get("/ready")
        body = r.json()
        assert body["checks"]["redis"] == "ok"


class TestSecurityHeaders:
    """SecurityHeadersMiddleware adds protective headers to every response."""

    async def test_security_headers_present(self, client: AsyncClient, admin_token: str):
        h = {"Authorization": f"Bearer {admin_token}"}
        r = await client.get("/api/v1/shipments", headers=h)

        assert r.headers.get("X-Content-Type-Options") == "nosniff"
        assert r.headers.get("X-Frame-Options") == "DENY"
        assert r.headers.get("Referrer-Policy") == "strict-origin-when-cross-origin"
